#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

double area(double r) {
    return 3.14159265358979 * r * r;
}

double area(double w, double h) {
    return w * h;
}

double area(double a, double b, double c) {
    double p = (a + b + c) / 2;
    return std::sqrt(p * (p - a) * (p - b) * (p - c));
}

int main() {
    std::cout << std::fixed << std::setprecision(2);
    std::string shape;
    while (std::cin >> shape) {
        if (shape == "circle") {
            double r;
            std::cin >> r;
            std::cout << area(r) << '\n';
        } else if (shape == "rect") {
            double w, h;
            std::cin >> w >> h;
            std::cout << area(w, h) << '\n';
        } else {
            double a, b, c;
            std::cin >> a >> b >> c;
            if (a >= b + c || b >= a + c || c >= a + b) {
                std::cout << "нет\n";
            } else {
                std::cout << area(a, b, c) << '\n';
            }
        }
    }
    return 0;
}

