#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

template <typename T>
T smallest(const std::vector<T> &v) {
    T best = v[0];
    for (const auto &x : v) {
        if (x < best) {
            best = x;
        }
    }
    return best;
}

template <typename T>
T largest(const std::vector<T> &v) {
    T best = v[0];
    for (const auto &x : v) {
        if (best < x) {
            best = x;
        }
    }
    return best;
}

template <typename T>
std::size_t count_distinct(std::vector<T> v) {
    std::sort(v.begin(), v.end());
    return static_cast<std::size_t>(std::unique(v.begin(), v.end()) - v.begin());
}

template <typename T>
void report(int n) {
    std::vector<T> values(static_cast<std::size_t>(n));
    for (auto &x : values) {
        std::cin >> x;
    }
    std::cout << "минимум " << smallest(values) << ", максимум " << largest(values)
              << ", различных " << count_distinct(values) << '\n';
}

int main() {
    std::string type;
    int n;
    if (!(std::cin >> type >> n) || n < 1) {
        return 0;
    }
    if (type == "int") {
        report<long long>(n);
    } else {
        report<std::string>(n);
    }
    return 0;
}

