#include <iostream>
#include <string>

template <typename T>
T repeat_add(T value, int times) {
    T result = value;
    for (int i = 1; i < times; i++) {
        result = result + value;
    }
    return result;
}

int main() {
    std::cout << repeat_add(5, 3) << ' ' << repeat_add(std::string("ab"), 3) << '\n';
    return 0;
}
